text:
{{(() => {
     if (GeocodeNewPickupAddress.isLoading) return (appsmith.store.bo_lang === 'en' ? "Searching the address..." : "Търсим адреса...");
     const w = (BoWarehouse.data || [])[0];
     if (w && w.address && NewPickupAddressInput.text === w.address) return (appsmith.store.bo_lang === 'en' ? "✓ Your warehouse" : "✓ Вашият склад");
     if (NewPickupLatHidden.text && NewPickupLngHidden.text) return (appsmith.store.bo_lang === 'en' ? "✓ Address found" : "✓ Адресът е намерен");
     if (NewPickupAddressInput.text?.length > 3 && !GeocodeNewPickupAddress.isLoading) return (appsmith.store.bo_lang === 'en' ? "✗ Address not found — check the spelling" : "✗ Адресът не е намерен — проверете изписването");
     return (appsmith.store.bo_lang === 'en' ? "Enter an address" : "Въведете адрес");
   })()}}

textColor:
{{(() => {
     if (GeocodeNewPickupAddress.isLoading) return "#F59E0B";
     if (NewPickupLatHidden.text && NewPickupLngHidden.text) return "#10B981";
     if (NewPickupAddressInput.text?.length > 3) return "#EF4444";
     return "#6B7280";
   })()}}
